            if(~arst_n) begin
                field_storage.IOQ[i0].CQ_CFG.iv.value <= 3'h0;
            end else begin
                if(field_combo.IOQ[i0].CQ_CFG.iv.load_next) begin
                    field_storage.IOQ[i0].CQ_CFG.iv.value <= field_combo.IOQ[i0].CQ_CFG.iv.next;
                end
            end
        end
        assign hwif_out.IOQ[i0].CQ_CFG.iv.value = field_storage.IOQ[i0].CQ_CFG.iv.value;
        // Field: nvme_regs.IOQ[].CQ_CFG.ien
        always_comb begin
            automatic logic [0:0] next_c;
            automatic logic load_next_c;
            next_c = field_storage.IOQ[i0].CQ_CFG.ien.value;
            load_next_c = '0;
            if(decoded_reg_strb.IOQ[i0].CQ_CFG && decoded_req_is_wr) begin // SW write
                next_c = (field_storage.IOQ[i0].CQ_CFG.ien.value & ~decoded_wr_biten[24:24]) | (decoded_wr_data[24:24] & decoded_wr_biten[24:24]);
                load_next_c = '1;
            end
            field_combo.IOQ[i0].CQ_CFG.ien.next = next_c;
            field_combo.IOQ[i0].CQ_CFG.ien.load_next = load_next_c;
        end
        always_ff @(posedge clk or negedge arst_n) begin
            if(~arst_n) begin
                field_storage.IOQ[i0].CQ_CFG.ien.value <= 1'h0;
            end else begin
                if(field_combo.IOQ[i0].CQ_CFG.ien.load_next) begin
                    field_storage.IOQ[i0].CQ_CFG.ien.value <= field_combo.IOQ[i0].CQ_CFG.ien.next;
                end
            end
        end
        assign hwif_out.IOQ[i0].CQ_CFG.ien.value = field_storage.IOQ[i0].CQ_CFG.ien.value;
        // Field: nvme_regs.IOQ[].CQ_CFG.en
        always_comb begin
            automatic logic [0:0] next_c;
            automatic logic load_next_c;
            next_c = field_storage.IOQ[i0].CQ_CFG.en.value;
            load_next_c = '0;
            if(decoded_reg_strb.IOQ[i0].CQ_CFG && decoded_req_is_wr) begin // SW write
                next_c = (field_storage.IOQ[i0].CQ_CFG.en.value & ~decoded_wr_biten[31:31]) | (decoded_wr_data[31:31] & decoded_wr_biten[31:31]);
                load_next_c = '1;
            end else if(hwif_in.IOQ[i0].CQ_CFG.en.hwclr) begin // HW Clear
                next_c = '0;
                load_next_c = '1;
            end
            field_combo.IOQ[i0].CQ_CFG.en.next = next_c;
            field_combo.IOQ[i0].CQ_CFG.en.load_next = load_next_c;
        end
        always_ff @(posedge clk or negedge arst_n) begin
            if(~arst_n) begin
                field_storage.IOQ[i0].CQ_CFG.en.value <= 1'h0;
            end else begin
                if(field_combo.IOQ[i0].CQ_CFG.en.load_next) begin
                    field_storage.IOQ[i0].CQ_CFG.en.value <= field_combo.IOQ[i0].CQ_CFG.en.next;
                end
            end
        end
        assign hwif_out.IOQ[i0].CQ_CFG.en.value = field_storage.IOQ[i0].CQ_CFG.en.value;
    end

    //--------------------------------------------------------------------------
    // Write response
    //--------------------------------------------------------------------------
    assign cpuif_wr_ack = decoded_req & decoded_req_is_wr;
    // Writes are always granted with no error response
    assign cpuif_wr_err = decoded_err;

    //--------------------------------------------------------------------------
    // Readback
    //--------------------------------------------------------------------------

    logic [11:0] rd_mux_addr;
    assign rd_mux_addr = decoded_addr;

    logic readback_err;
    logic readback_done;
    logic [31:0] readback_data;
    always_comb begin
        automatic logic [31:0] readback_data_var;
        readback_data_var = '0;
        if(rd_mux_addr == 12'h0) begin
            readback_data_var[0] = field_storage.CTRL.ien_cmd.value;
            readback_data_var[1] = field_storage.CTRL.ien_xfer.value;
        end
        if(rd_mux_addr == 12'h4) begin
            readback_data_var[0] = hwif_in.STATUS.rdy.next;
            readback_data_var[1] = hwif_in.STATUS.cfs.next;
            readback_data_var[2] = hwif_in.STATUS.en.next;
            readback_data_var[5:4] = hwif_in.STATUS.shst.next;
            readback_data_var[12:8] = hwif_in.STATUS.cmds.next;
            readback_data_var[20:16] = hwif_in.STATUS.free.next;
        end
        if(rd_mux_addr == 12'h8) begin
            readback_data_var[0] = field_storage.EVENT.enable.value;
            readback_data_var[1] = field_storage.EVENT.reset.value;
            readback_data_var[2] = field_storage.EVENT.shutdown.value;
            readback_data_var[3] = field_storage.EVENT.db_err.value;
            readback_data_var[4] = field_storage.EVENT.fetch_err.value;
            readback_data_var[5] = field_storage.EVENT.cqe_err.value;
        end
        if(rd_mux_addr == 12'hc) begin
            readback_data_var[5:0] = field_storage.EVENT_EN.en.value;
        end
        if(rd_mux_addr == 12'h10) begin
            readback_data_var[31:0] = hwif_in.CC.value.next;
        end
        if(rd_mux_addr == 12'h14) begin
            readback_data_var[31:10] = field_storage.CMDBUF.base.value;
        end
        if(rd_mux_addr == 12'h18) begin
            readback_data_var[3:0] = hwif_in.CMD.slot.next;
            readback_data_var[18:16] = hwif_in.CMD.sqid.next;
            readback_data_var[31] = hwif_in.CMD.valid.next;
        end
        if(rd_mux_addr == 12'h20) begin
            readback_data_var[2:0] = field_storage.DB_ERR.qid.value;
            readback_data_var[3] = field_storage.DB_ERR.cq.value;
            readback_data_var[31:16] = field_storage.DB_ERR.value.value;
        end
        if(rd_mux_addr == 12'h24) begin
            readback_data_var[31:0] = hwif_in.FETCHES.count.next;
        end
        if(rd_mux_addr == 12'h30) begin
            readback_data_var[31:0] = hwif_in.AQA.value.next;
        end
        if(rd_mux_addr == 12'h34) begin
            readback_data_var[31:0] = hwif_in.ASQ_LO.value.next;
        end
        if(rd_mux_addr == 12'h38) begin
            readback_data_var[31:0] = hwif_in.ASQ_HI.value.next;
        end
        if(rd_mux_addr == 12'h3c) begin
            readback_data_var[31:0] = hwif_in.ACQ_LO.value.next;
        end
        if(rd_mux_addr == 12'h40) begin
            readback_data_var[31:0] = hwif_in.ACQ_HI.value.next;
        end
        if(rd_mux_addr == 12'h50) begin
            readback_data_var[31:0] = field_storage.XF_PRP1_LO.value.value;
        end
        if(rd_mux_addr == 12'h54) begin
            readback_data_var[31:0] = field_storage.XF_PRP1_HI.value.value;
        end
        if(rd_mux_addr == 12'h58) begin
            readback_data_var[31:0] = field_storage.XF_PRP2_LO.value.value;
        end
        if(rd_mux_addr == 12'h5c) begin
            readback_data_var[31:0] = field_storage.XF_PRP2_HI.value.value;
        end
        if(rd_mux_addr == 12'h60) begin
            readback_data_var[31:2] = field_storage.XF_LADDR.addr.value;
        end
        if(rd_mux_addr == 12'h64) begin
            readback_data_var[17:2] = field_storage.XF_LEN.bytes.value;
        end
        if(rd_mux_addr == 12'h68) begin
            readback_data_var[1] = field_storage.XF_CTRL.d2h.value;
        end
        if(rd_mux_addr == 12'h6c) begin
            readback_data_var[0] = hwif_in.XF_STATUS.busy.next;
            readback_data_var[1] = field_storage.XF_STATUS.done.value;
            readback_data_var[2] = field_storage.XF_STATUS.err.value;
            readback_data_var[11:8] = field_storage.XF_STATUS.cause.value;
        end
        if(rd_mux_addr == 12'h70) begin
            readback_data_var[31:0] = hwif_in.XF_CYCLES.count.next;
        end
        if(rd_mux_addr == 12'h80) begin
            readback_data_var[31:0] = field_storage.CQE_DW0.value.value;
        end
        if(rd_mux_addr == 12'h84) begin
            readback_data_var[15:0] = field_storage.CQE_INFO.cid.value;
            readback_data_var[18:16] = field_storage.CQE_INFO.sqid.value;
        end
        if(rd_mux_addr == 12'h88) begin
            readback_data_var[2:0] = field_storage.CQE_CTRL.cqid.value;
            readback_data_var[31:17] = field_storage.CQE_CTRL.status.value;
        end
        if(rd_mux_addr == 12'h8c) begin
            readback_data_var[2:0] = hwif_in.CQE_STATUS.count.next;
            readback_data_var[4] = hwif_in.CQE_STATUS.full.next;
            readback_data_var[5] = hwif_in.CQE_STATUS.cq_full.next;
            readback_data_var[8] = field_storage.CQE_STATUS.drop.value;
            readback_data_var[9] = field_storage.CQE_STATUS.werr.value;
        end
        if(rd_mux_addr == 12'h90) begin
            readback_data_var[31:0] = hwif_in.CQES.count.next;
        end
        for(int i0=0; i0<4; i0++) begin
            if(rd_mux_addr == 12'h100 + (12)'(i0) * 12'h20) begin
                readback_data_var[31:12] = field_storage.IOQ[i0].SQB_LO.base.value;
            end
            if(rd_mux_addr == 12'h104 + (12)'(i0) * 12'h20) begin
                readback_data_var[31:0] = field_storage.IOQ[i0].SQB_HI.base.value;
            end
            if(rd_mux_addr == 12'h108 + (12)'(i0) * 12'h20) begin
                readback_data_var[11:0] = field_storage.IOQ[i0].SQ_CFG.size.value;
                readback_data_var[18:16] = field_storage.IOQ[i0].SQ_CFG.cqid.value;
                readback_data_var[31] = field_storage.IOQ[i0].SQ_CFG.en.value;
            end
            if(rd_mux_addr == 12'h10c + (12)'(i0) * 12'h20) begin
                readback_data_var[31:12] = field_storage.IOQ[i0].CQB_LO.base.value;
            end
            if(rd_mux_addr == 12'h110 + (12)'(i0) * 12'h20) begin
                readback_data_var[31:0] = field_storage.IOQ[i0].CQB_HI.base.value;
            end
            if(rd_mux_addr == 12'h114 + (12)'(i0) * 12'h20) begin
                readback_data_var[11:0] = field_storage.IOQ[i0].CQ_CFG.size.value;
                readback_data_var[18:16] = field_storage.IOQ[i0].CQ_CFG.iv.value;
                readback_data_var[24] = field_storage.IOQ[i0].CQ_CFG.ien.value;
                readback_data_var[31] = field_storage.IOQ[i0].CQ_CFG.en.value;
            end
        end
        for(int i0=0; i0<5; i0++) begin
            if(rd_mux_addr == 12'h200 + (12)'(i0) * 12'h4) begin
                readback_data_var[11:0] = hwif_in.SQ_PTR[i0].head.next;
                readback_data_var[27:16] = hwif_in.SQ_PTR[i0].tail.next;
            end
        end
        for(int i0=0; i0<5; i0++) begin
            if(rd_mux_addr == 12'h220 + (12)'(i0) * 12'h4) begin
                readback_data_var[11:0] = hwif_in.CQ_PTR[i0].head.next;
                readback_data_var[27:16] = hwif_in.CQ_PTR[i0].tail.next;
                readback_data_var[31] = hwif_in.CQ_PTR[i0].phase.next;
            end
        end
        readback_data = readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = decoded_err;
    end

    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
